SELECT id, store_id, product_id, sale_date, units, revenue, AVG(units) OVER (PARTITION BY store_id) AS store_id_avg_units, COUNT(units) OVER (PARTITION BY product_id) AS product_id_count_units, LAST_VALUE(units) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_units, LEAD(units, 1, 0) OVER (PARTITION BY store_id ORDER BY units, id) AS next_units FROM store_sales
